import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.eFe5Lsvn.js";const l="/Mayhem/img/field-mode.jpg",g=JSON.parse('{"title":"Field and obstacles","description":"","frontmatter":{},"headers":[],"relativePath":"app/field.md","filePath":"app/field.md"}'),s={name:"app/field.md"};function i(n,e,d,c,h,b){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="field-and-obstacles" tabindex="-1">Field and obstacles <a class="header-anchor" href="#field-and-obstacles" aria-label="Permalink to &quot;Field and obstacles&quot;">​</a></h1><p>Switch to <strong>Field</strong> in the top bar. Every obstacle here applies to all paths.</p><p><img src="'+l+'" alt="Field mode"></p><h2 id="drawing-obstacles" tabindex="-1">Drawing obstacles <a class="header-anchor" href="#drawing-obstacles" aria-label="Permalink to &quot;Drawing obstacles&quot;">​</a></h2><ul><li><strong>Polygon</strong> (<kbd>P</kbd>): click corners; click the first corner, double-click or press <kbd>Enter</kbd> to finish.</li><li><strong>Circle</strong> (<kbd>C</kbd>): drag from the center.</li><li>Select an obstacle to drag it, drag its corners, double-click an edge to add a corner, or <kbd>⇧</kbd>-click a corner to remove it.</li></ul><h2 id="the-obstacle-list" tabindex="-1">The obstacle list <a class="header-anchor" href="#the-obstacle-list" aria-label="Permalink to &quot;The obstacle list&quot;">​</a></h2><ul><li>Checkboxes in the sidebar enable or disable obstacles.</li><li>The REBUILT <strong>bumps</strong> and the overhead <strong>trench openings</strong> start disabled, since most robots drive over or under them. Enable the trenches if your robot is taller than 22.25 in.</li><li><strong>Copy to other alliance</strong> (the flip icon in the obstacle panel) mirrors an obstacle using the field symmetry.</li><li><strong>Clearance margin</strong> is extra space the robot keeps from that obstacle.</li><li><strong>Fuel sim</strong> (per obstacle) chooses whether it blocks fuel. See <a href="/Mayhem/app/fuel-sim">Fuel sim</a>.</li></ul><h2 id="field-settings" tabindex="-1">Field settings <a class="header-anchor" href="#field-settings" aria-label="Permalink to &quot;Field settings&quot;">​</a></h2><p>The field panel sets the field&#39;s name, length and width, the red-alliance flip (<strong>Rotate 180°</strong> for REBUILT, or <strong>Mirror</strong>) and the wall clearance. You can replace the whole field from a preset with <strong>Load</strong>; undo is available.</p><p>The geometry comes from the 2026 field drawings. Edit it to match your venue.</p>',10)])])}const f=t(s,[["render",i]]);export{g as __pageData,f as default};
